package com.turboio.addon;

import java.io.*;import java.nio.channels.FileChannel;import java.nio.file.*;import java.util.*;

/** Bounded retry cadence and durable fair discovery cursor, without credentials. */
final class AudioAutoSchedule implements AutoCloseable {
 private final AtomicDocument document;private final File file;private final AudioConfig config;private final AudioUploadOutbox.Guard guard;private Map<String,Object> state;
 AudioAutoSchedule(File files,AudioConfig config,AudioUploadOutbox.Guard guard)throws IOException{
  this.config=config;this.guard=guard;guard.check();File base=files.getCanonicalFile();safe(base,true);for(String component:new String[]{"audio-auto-sync",config.connection.binding(),config.account}){File next=new File(base,component);safe(next,true);if(!next.exists()){AudioUploadWire.check(next.mkdir(),"AUDIO_AUTO_DIRECTORY");sync(base);}base=next;}file=new File(base,"state.json");paths();document=new AtomicDocument(file,4096);
  try{Object raw=document.read();state=raw==null?WireJson.object("schema",1,"binding",config.connection.binding(),"account",config.account,"config",config.fingerprint(),"cursor","","attempt",0,"next",0,"failures",0,"error",""):WireJson.map(raw);AudioUploadWire.keys(state,"schema","binding","account","config","cursor","attempt","next","failures","error");AudioUploadWire.check(AudioUploadWire.number(state.get("schema"))==1&&config.account.equals(state.get("account"))&&config.connection.binding().equals(state.get("binding")),"AUDIO_AUTO_INVALID");AudioUploadWire.hash(state.get("config"));String cursor=(String)state.get("cursor"),error=(String)state.get("error");AudioUploadWire.check(cursor.isEmpty()||cursor.matches("[a-f0-9]{64}"),"AUDIO_AUTO_INVALID");AudioUploadWire.check(error.matches("[A-Z_]{0,80}")&&AudioUploadWire.number(state.get("failures"))<=5,"AUDIO_AUTO_INVALID");AudioUploadWire.number(state.get("attempt"));AudioUploadWire.number(state.get("next"));File partial=new File(file+".partial");if(partial.exists()){AudioUploadWire.check(partial.length()<=4096,"AUDIO_AUTO_UNCERTAIN");Files.move(partial.toPath(),new File(file+".interrupted").toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);sync(file.getParentFile());Map<String,Object> recovered=WireJson.map(WireJson.copy(state));recovered.put("next",0L);recovered.put("error","AUDIO_RUN_INTERRUPTED");save(recovered);}}
  catch(IOException|RuntimeException e){document.close();throw e;}
 }
 private static void safe(File f,boolean dir)throws IOException{AudioUploadWire.check(!Files.isSymbolicLink(f.toPath())&&f.getAbsoluteFile().equals(f.getCanonicalFile()),"AUDIO_AUTO_PATH");if(f.exists())AudioUploadWire.check(dir?f.isDirectory():f.isFile(),"AUDIO_AUTO_PATH");}
 private static void sync(File dir)throws IOException{try(FileChannel c=FileChannel.open(dir.toPath(),StandardOpenOption.READ)){c.force(true);}}
 private void paths()throws IOException{safe(file.getParentFile(),true);for(String n:new String[]{"state.json","state.json.lock","state.json.partial","state.json.interrupted"})safe(new File(file.getParentFile(),n),false);}
 private void save(Map<String,Object> next)throws IOException{guard.check();paths();document.save(next);sync(file.getParentFile());state=next;}
 boolean due(long now,boolean recovered)throws IOException{guard.check();AudioUploadWire.check(now>0&&config.enabled&&config.connection.expiresAt>now,"AUDIO_CREDENTIAL_EXPIRED");long previous=AudioUploadWire.number(state.get("attempt")),at=AudioUploadWire.number(state.get("next"));return !config.fingerprint().equals(state.get("config"))||now<previous||now>=at||recovered&&AudioUploadWire.number(state.get("failures"))>0&&now-previous>=30000;}
 boolean begin(long now,boolean recovered,boolean force)throws IOException{guard.check();if(!due(now,recovered)&&!force)return false;AudioUploadWire.check(config.connection.expiresAt>now,"AUDIO_CREDENTIAL_EXPIRED");Map<String,Object> next=WireJson.map(WireJson.copy(state));boolean changed=!config.fingerprint().equals(state.get("config"));next.put("config",config.fingerprint());next.put("attempt",now);next.put("next",Math.addExact(now,120000));next.put("error","AUDIO_RUN_UNCONFIRMED");if(changed)next.put("failures",0L);save(next);return true;}

 String cursor(){return (String)state.get("cursor");}
 void advance(String cursor)throws IOException{AudioUploadWire.hash(cursor);Map<String,Object> next=WireJson.map(WireJson.copy(state));next.put("cursor",cursor);save(next);}
 void finish(long now,boolean progressed,String error)throws IOException{AudioUploadWire.check(now>0&&error!=null&&error.matches("[A-Z_]{0,80}"),"AUDIO_AUTO_INVALID");Map<String,Object> next=WireJson.map(WireJson.copy(state));long failures=progressed||error.isEmpty()?0:Math.min(5,AudioUploadWire.number(state.get("failures"))+1);next.put("failures",failures);next.put("error",error);next.put("next",Math.addExact(now,progressed?1000:error.isEmpty()?60000:Math.min(300000,30000L<<(failures-1))));save(next);}
 public void close()throws IOException{document.close();}
}
